diff --git a/broker/cmd/agentosd/questions.go b/broker/cmd/agentosd/questions.go
new file mode 100644
index 00000000..deed7dff
--- /dev/null
+++ b/broker/cmd/agentosd/questions.go
@@ -0,0 +1,116 @@
+package main
+
+import (
+	"context"
+	"encoding/json"
+	"errors"
+	"log"
+	"path/filepath"
+	"sync/atomic"
+	"time"
+
+	"github.com/ghbmrk/agentos/broker/clock"
+	"github.com/ghbmrk/agentos/broker/daemon"
+	"github.com/ghbmrk/agentos/broker/guest"
+	"github.com/ghbmrk/agentos/broker/owner"
+	"github.com/ghbmrk/agentos/broker/question"
+	"github.com/ghbmrk/agentos/broker/vm"
+)
+
+// questions is the owner-question book (P3-8) live (W9). The daemon's
+// handlers take it before it opens, since the book texts through the
+// owner channel the daemon makes; until it opens, and for good when there
+// is no owner channel, nothing is answered and no tool is offered.
+type questions struct{ b atomic.Pointer[question.Book] }
+
+// Answer is the owner channel's answer hook (control.Handler.Answer).
+func (q *questions) Answer(ctx context.Context, msg string) (string, bool) {
+	b := q.b.Load()
+	if b == nil {
+		return "", false
+	}
+	return b.Answer(ctx, msg)
+}
+
+// List and Call serve the question tools on each guest socket.
+func (q *questions) List() []map[string]any { return question.Tools }
+
+func (q *questions) Call(ctx context.Context, machine, lineage, name string, args json.RawMessage) (string, bool, error) {
+	b := q.b.Load()
+	if b == nil {
+		if name == question.ToolAsk || name == question.ToolStatus {
+			return "", true, errors.New("the broker cannot text the owner now")
+		}
+		return "", false, nil
+	}
+	return question.GuestTools{Book: b}.Call(ctx, machine, lineage, name, args)
+}
+
+// questionConfig is where the book and the box clock keep their state.
+type questionConfig struct {
+	Path, ClockPath string
+}
+
+// open starts the box clock (P2-9) and the question book on the owner
+// channel. Deadlines run on the guard's time and hold while it is
+// restricted (TIM-1). Reveal raises the reading machine to private before it
+// sees the owner's words (REV-5). Questions and approval requests share
+// the gate's CH-15 budget, approval requests first (question Q3): the
+// gate reserves each question's text under its own lock.
+func (q *questions) open(ctx context.Context, d *daemon.Daemon, pre *preempter, cfg questionConfig) (*clock.Guard, error) {
+	ch := d.Owner()
+	if ch == nil {
+		return nil, errors.New("no owner channel")
+	}
+	// No Notify yet: the guard's texts tell the owner that pre-allowances,
+	// request expiry and updates are playing safe, and those move onto the
+	// guard only with the rest of P2-9's carry-forward (clock K7). Until
+	// then a restriction holds questions without a text.
+	guard, err := clock.New(clock.Config{
+		Synced:    clock.Synced,
+		StatePath: cfg.ClockPath,
+		Logf:      log.Printf,
+	})
+	if err != nil {
+		return nil, err
+	}
+	b, err := question.New(question.Config{
+		Send: ch.Notify,
+		Now:  guard.Now,
+		Reveal: func(machine string) error {
+			m := pre.m.Load()
+			if m == nil {
+				return errors.New("machine manager not open")
+			}
+			return m.RaiseLabel(machine, vm.Private)
+		},
+		Path:          cfg.Path,
+		Hidden:        owner.SecretShaped,
+		ApprovalsOpen: ch.ApprovalsOpen,
+		Reserve:       d.Gate().Reserve,
+		Logf:          log.Printf,
+	})
+	if err != nil {
+		return nil, err
+	}
+	q.b.Store(b)
+	go guard.Run(ctx)
+	go b.Run(ctx, 30*time.Second)
+	return guard, nil
+}
+
+// wire gives the daemon the answer hook; call it before daemon.Run.
+func (q *questions) wire(cfg *daemon.Config) { cfg.Answer = q.Answer }
+
+// tools is what the guest plane serves beside the effect tools: the
+// question tools once the book is open, else none.
+func (q *questions) tools() guest.Tools {
+	if q.b.Load() == nil {
+		return nil
+	}
+	return q
+}
+
+func defaultQuestionConfig(dir string) questionConfig {
+	return questionConfig{Path: filepath.Join(dir, "questions.json"), ClockPath: filepath.Join(dir, "clock.json")}
+}
diff --git a/broker/cmd/agentosd/questions_test.go b/broker/cmd/agentosd/questions_test.go
new file mode 100644
index 00000000..417ef0d1
--- /dev/null
+++ b/broker/cmd/agentosd/questions_test.go
@@ -0,0 +1,102 @@
+package main
+
+import (
+	"context"
+	"encoding/json"
+	"os"
+	"path/filepath"
+	"strings"
+	"testing"
+	"time"
+
+	"github.com/ghbmrk/agentos/broker/admission"
+	"github.com/ghbmrk/agentos/broker/daemon"
+	"github.com/ghbmrk/agentos/broker/question"
+)
+
+// REQ: CAP-10, CH-15, ARC-6
+
+// Agents' questions run in agentosd (W9): the guest tools reach the book
+// with the lineage as asker, the owner channel's answer hook and the
+// gate's shared budget are the book's, and with no owner channel nothing
+// is offered.
+func TestQuestionsRunInAgentosd(t *testing.T) {
+	dir := t.TempDir()
+	qs := &questions{}
+	cfg := daemon.Config{
+		JournalPath: filepath.Join(dir, "journal.log"), SocketDir: filepath.Join(dir, "run"),
+		OwnerNumber: ownerNum, ModemUID: os.Getuid(), Admission: admission.Config{CapacityMB: 4500, HeadroomMB: 600},
+		OwnerState: filepath.Join(dir, "owner.json"),
+	}
+	qs.wire(&cfg) // as main does
+	ctx, cancel := context.WithCancel(context.Background())
+	defer cancel()
+	if _, ok := qs.Answer(ctx, "Q100 yes"); ok {
+		t.Fatal("answered before the book opened")
+	}
+	if qs.tools() != nil {
+		t.Fatal("tools offered before the book opened")
+	}
+	d, err := daemon.Run(ctx, cfg)
+	if err != nil {
+		t.Fatal(err)
+	}
+	guard, err := qs.open(ctx, d, &preempter{}, defaultQuestionConfig(dir))
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer guard.Flush()
+	if qs.tools() == nil {
+		t.Fatal("no tools for the guest plane once the book is open")
+	}
+
+	text, handled, err := qs.Call(ctx, "agent", "agent", question.ToolAsk,
+		json.RawMessage(`{"request_id":"q1","question":"Which slot?","choices":["9:00","9:30"],"default":"9:30","wait_minutes":30}`))
+	if err != nil || !handled {
+		t.Fatalf("ask: %v %v", handled, err)
+	}
+	var res question.ToolResult
+	if err := json.Unmarshal([]byte(text), &res); err != nil || res.Question != "Q100" {
+		t.Fatalf("ask result %s", text)
+	}
+	if _, _, err := qs.Call(ctx, "other", "other", question.ToolStatus, json.RawMessage(`{"request_id":"q1"}`)); err == nil {
+		t.Fatal("another lineage read the question")
+	}
+	if _, handled, _ := qs.Call(ctx, "agent", "agent", "effect_request", nil); handled {
+		t.Fatal("took the effect tool")
+	}
+	// Hidden is owner.SecretShaped: an answer only it calls secret-shaped
+	// (a short code beside a code word; the book's own checks pass it) is
+	// refused.
+	if reply, ok := cfg.Answer(ctx, "Q100 my pin is A1B2"); !ok || !strings.Contains(reply, "Codes and keys") {
+		t.Fatalf("secret-shaped answer: %q %v", reply, ok)
+	}
+	if reply, ok := cfg.Answer(ctx, "Q100 9:00"); !ok || !strings.Contains(reply, "Q100") {
+		t.Fatalf("answer hook: %q %v", reply, ok)
+	}
+	// Reserve is the gate's: with the hour's CH-15 budget spent on the
+	// gate, a new question is held, not texted.
+	for d.Gate().Reserve(time.Now()) {
+	}
+	text, _, err = qs.Call(ctx, "agent", "agent", question.ToolAsk,
+		json.RawMessage(`{"request_id":"q2","question":"Lunch at noon?","default":"yes","wait_minutes":30}`))
+	if err != nil || !strings.Contains(text, `"state":"held"`) {
+		t.Fatalf("question with the budget spent: %s %v", text, err)
+	}
+	// A locked session never reaches the hook, so the reply is the unlock
+	// prompt (the hook's own tests cover the unlocked path).
+	if got := d.Owner().Handle(ctx, ownerNum, "Q100 9:30"); len(got) != 1 || !strings.HasPrefix(got[0], "Locked.") {
+		t.Fatalf("locked reply: %q", got)
+	}
+
+	// No owner channel: the book does not open.
+	cfg2 := cfg
+	cfg2.OwnerState, cfg2.JournalPath, cfg2.SocketDir = "", filepath.Join(dir, "j2.log"), filepath.Join(dir, "run2")
+	d2, err := daemon.Run(ctx, cfg2)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if _, err := (&questions{}).open(ctx, d2, &preempter{}, defaultQuestionConfig(t.TempDir())); err == nil {
+		t.Fatal("opened with no owner channel")
+	}
+}
